css:
.fx-v360{width:min(460px,100%);text-align:center}
.fx-v360 .stage{position:relative;aspect-ratio:1;border-radius:var(--radius);background:radial-gradient(circle at 50% 60%,color-mix(in srgb,var(--primary) 12%,var(--surface)),var(--surface));display:grid;place-items:center;cursor:grab;touch-action:pan-y;user-select:none;perspective:900px;border:1px solid var(--border)}
.fx-v360 .stage:active{cursor:grabbing}
.fx-v360 .stage:focus-visible{outline:2px solid var(--primary);outline-offset:3px}
.fx-v360 .obj{width:42%;aspect-ratio:1;position:relative;transform-style:preserve-3d;transform:rotateX(-14deg) rotateY(var(--a,0deg))}
.fx-v360 .obj i{position:absolute;inset:0;border:2px solid var(--on-primary);background:color-mix(in srgb,var(--primary) 82%,var(--accent));backface-visibility:hidden}.fx-v360 .obj i:nth-child(5){transform:rotateX(90deg) translateZ(calc(var(--s,100px)/2));background:color-mix(in srgb,var(--accent) 70%,#fff)}
.fx-v360 .obj i:nth-child(1){transform:translateZ(calc(var(--s,100px)/2))}.fx-v360 .obj i:nth-child(2){transform:rotateY(90deg) translateZ(calc(var(--s,100px)/2));background:color-mix(in srgb,var(--primary) 60%,var(--accent))}
.fx-v360 .obj i:nth-child(3){transform:rotateY(180deg) translateZ(calc(var(--s,100px)/2));background:var(--accent)}.fx-v360 .obj i:nth-child(4){transform:rotateY(-90deg) translateZ(calc(var(--s,100px)/2));background:color-mix(in srgb,var(--secondary) 80%,var(--primary))}
.fx-v360 .shadow{position:absolute;bottom:14%;width:34%;height:6%;border-radius:50%;background:var(--text);opacity:.18;filter:blur(8px)}
.fx-v360 .bar{height:.4em;border-radius:99px;background:var(--border);margin:1em auto 0;width:70%;overflow:hidden}
.fx-v360 .bar span{display:block;height:100%;width:var(--p,0%);background:var(--primary)}
.fx-v360 p{margin-top:.7em;font-size:.88em;opacity:.65}
